<?php
defined('ABSPATH') || exit;
require_once __DIR__.'/accounts.php';
add_action('after_setup_theme', function(){ add_theme_support('title-tag'); add_theme_support('woocommerce'); add_theme_support('wc-product-gallery-slider'); });
add_action('wp_enqueue_scripts', function(){ wp_enqueue_style('study',get_stylesheet_uri(),[],filemtime(__DIR__.'/style.css')); wp_enqueue_script('study',get_template_directory_uri().'/app.js',[],filemtime(__DIR__.'/app.js'),true); wp_localize_script('study','studyConfig',['ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('study-cart'),'checkout'=>function_exists('wc_get_checkout_url')?wc_get_checkout_url():'']); });
add_filter('wp_robots',function($r){$r['noindex']=true;$r['nofollow']=true;return $r;});
add_filter('woocommerce_product_get_image',function($html,$p){$images=$p->get_meta('_study_images');return $images?'<img src="'.esc_url($images[0]).'" alt="'.esc_attr($p->get_name()).'">':$html;},10,2);
add_filter('woocommerce_single_product_image_thumbnail_html',function($html,$id){global $product;$images=$product?$product->get_meta('_study_images'):[];if(!$images)return $html;return implode('',array_map(function($url){return '<img loading="lazy" src="'.esc_url($url).'" alt="">';},array_slice($images,0,5)));},10,2);
function study_cart(){ $items=[];if(WC()->cart){foreach(WC()->cart->get_cart() as $key=>$line){$p=$line['data'];$images=$p->get_meta('_study_images');$items[]=['key'=>$key,'id'=>$p->get_id(),'name'=>$p->get_name(),'quantity'=>$line['quantity'],'price'=>(float)$p->get_price(),'image'=>$images[0]??''];}}return ['items'=>$items,'total'=>WC()->cart?(float)WC()->cart->get_cart_contents_total():0,'count'=>WC()->cart?WC()->cart->get_cart_contents_count():0];}
add_action('wp_ajax_study_cart','study_cart_endpoint');add_action('wp_ajax_nopriv_study_cart','study_cart_endpoint');
function study_cart_endpoint(){check_ajax_referer('study-cart','nonce');if(!function_exists('WC'))wp_send_json_error('WooCommerce unavailable');if(!WC()->cart)wc_load_cart();try{if(isset($_POST['add'])){if(!WC()->cart->add_to_cart(absint($_POST['add'])))throw new Exception('This item cannot be added.');}if(isset($_POST['remove']))WC()->cart->remove_cart_item(sanitize_text_field($_POST['remove']));if(isset($_POST['quantity'],$_POST['key']))WC()->cart->set_quantity(sanitize_text_field($_POST['key']),max(0,absint($_POST['quantity'])));WC()->cart->calculate_totals();wp_send_json_success(study_cart());}catch(Throwable $e){wp_send_json_error($e->getMessage());}}
function study_catalog_data(){ $q=new WP_Query(['post_type'=>'product','posts_per_page'=>250,'orderby'=>'menu_order','order'=>'ASC','post_status'=>'publish']);$out=[];foreach($q->posts as $post){$p=wc_get_product($post->ID);$out[]=['id'=>$p->get_id(),'title'=>$p->get_name(),'url'=>get_permalink($p->get_id()),'price'=>(float)$p->get_price(),'regular'=>(float)$p->get_regular_price(),'images'=>$p->get_meta('_study_images')?:[],'tags'=>$p->get_meta('_study_tags')?:[],'available'=>$p->is_in_stock()];}return $out;}
